from taf.sbts.oam.coam.admin.schemas.procedure.lte_ccm_uplink import LTECCMUplink


class LTECCMUplinkNPrach(LTECCMUplink):
    def __init__(self, lncel_rdn, measurement_type, reporting_time_interval, reception_subframe,
                 exception_subframe, earfcn, accepted_timing_error, constant_offset, nb_repetitions, nb_subframe_offset,
                 config_index, preamble_index, subcarrier_offset, num_subcarriers, expection_bundle, reception_bundle,
                 root_seq_index=None, prach_cs=None, prach_hs_flag=None, phys_cell_id=None, tdd_frame_conf=None,
                 tdd_spec_subf_conf=None):
        super(LTECCMUplinkNPrach, self).__init__(lncel_rdn=lncel_rdn,
                                                 measurement_type=measurement_type,
                                                 reporting_time_interval=reporting_time_interval,
                                                 reception_subframe=reception_subframe,
                                                 exception_subframe=exception_subframe,
                                                 earfcn=earfcn,
                                                 root_seq_index=root_seq_index,
                                                 prach_cs=prach_cs,
                                                 prach_hs_flag=prach_hs_flag,
                                                 phys_cell_id=phys_cell_id,
                                                 tdd_frame_conf=tdd_frame_conf,
                                                 tdd_spec_subf_conf=tdd_spec_subf_conf)

        self.n_prach_params = {"acceptedTimingError": self.validate_param('acceptedTimingError',
                                                                          accepted_timing_error,
                                                                          [0, 65535]),
                               "constantOffset": self.validate_param('constantOffset',
                                                                     constant_offset,
                                                                     [0, 65535]),
                               "nbRepetitions": self.validate_param('nbRepetitions',
                                                                    nb_repetitions,
                                                                    validity_clause=(
                                                                        nb_repetitions in [
                                                                            'NBR_8', 'NBR_32'
                                                                        ]
                                                                    )),
                               "nbSubframeOffset": self.validate_param('nbSubframeOffset',
                                                                       nb_subframe_offset,
                                                                       [0, 255]),
                               "configIndex": self.validate_param('configIndex',
                                                                  config_index,
                                                                  [0, 2]),
                               "preambleIndex": self.validate_param('preambleIndex',
                                                                    preamble_index,
                                                                    [0, 47]),
                               "subcarrierOffset": self.validate_param('subcarrierOffset',
                                                                       subcarrier_offset,
                                                                       validity_clause=(
                                                                           subcarrier_offset in [
                                                                               'SCO_0', 'SCO_2', 'SCO_12', 'SCO_18',
                                                                               'SCO_24', 'SCO_34', 'SCO_36'
                                                                           ]
                                                                       )),
                               "numSubcarriers": self.validate_param('numSubcarriers',
                                                                     num_subcarriers,
                                                                     validity_clause=(
                                                                         num_subcarriers in [
                                                                             'NSC_12', 'NSC_24', 'NSC_36', 'NSC_48'
                                                                         ]
                                                                     )),
                               "expectionBundle": self.validate_param('expectionBundle',
                                                                      expection_bundle,
                                                                      [0, 3]),
                               "receptionBundle": self.validate_param('receptionBundle',
                                                                      reception_bundle,
                                                                      [1, 3])
                               }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_n_prach_params(parameter):
            return response_dict['params']['nPrachParams'][parameter]

        lncel_rdn = response_dict['lncel_rDN']
        measurement_type = response_dict['params']['measurementType']
        reporting_time_interval = response_dict['params']['reportingTimeInterval']
        reception_subframe = response_dict['params']['receptionSubframe']
        exception_subframe = response_dict['params']['expectionSubframe']
        earfcn = response_dict['params']['earfcn']
        root_seq_index = response_dict['params']['rootSeqIndex'] if 'rootSeqIndex' in response_dict['params'] else None
        prach_cs = response_dict['params']['prachCS'] if 'prachCS' in response_dict['params'] else None
        prach_hs_flag = response_dict['params']['prachHsFlag'] if 'prachHsFlag' in response_dict['params'] else None
        phys_cell_id = response_dict['params']['physCellId'] if 'physCellId' in response_dict['params'] else None
        tdd_frame_conf = response_dict['params']['tddFrameConf'] if 'tddFrameConf' in response_dict['params'] else None
        tdd_spec_subf_conf = response_dict['params']['tddSpecSubfConf'] if 'tddSpecSubfConf' in response_dict[
            'params'] else None

        n_prach_params = {
            "acceptedTimingError": _get_n_prach_params('acceptedTimingError'),
            "constantOffset": _get_n_prach_params('constantOffset'),
            "nbRepetitions": _get_n_prach_params('nbRepetitions'),
            "nbSubframeOffset": _get_n_prach_params('nbSubframeOffset'),
            "configIndex": _get_n_prach_params('configIndex'),
            "preambleIndex": _get_n_prach_params('preambleIndex'),
            "subcarrierOffset": _get_n_prach_params('subcarrierOffset'),
            "numSubcarriers": _get_n_prach_params('numSubcarriers'),
            "expectionBundle": _get_n_prach_params('expectionBundle'),
            "receptionBundle": _get_n_prach_params('receptionBundle')
        }

        return cls(lncel_rdn=lncel_rdn,
                   measurement_type=measurement_type,
                   reporting_time_interval=reporting_time_interval,
                   reception_subframe=reception_subframe,
                   exception_subframe=exception_subframe,
                   earfcn=earfcn,
                   accepted_timing_error=n_prach_params['acceptedTimingError'],
                   constant_offset=n_prach_params['constantOffset'],
                   nb_repetitions=n_prach_params['nbRepetitions'],
                   nb_subframe_offset=n_prach_params['nbSubframeOffset'],
                   config_index=n_prach_params['configIndex'],
                   preamble_index=n_prach_params['preambleIndex'],
                   subcarrier_offset=n_prach_params['subcarrierOffset'],
                   num_subcarriers=n_prach_params['numSubcarriers'],
                   expection_bundle=n_prach_params['expectionBundle'],
                   reception_bundle=n_prach_params['receptionBundle'],
                   root_seq_index=root_seq_index,
                   prach_cs=prach_cs,
                   prach_hs_flag=prach_hs_flag,
                   phys_cell_id=phys_cell_id,
                   tdd_frame_conf=tdd_frame_conf,
                   tdd_spec_subf_conf=tdd_spec_subf_conf)

    def as_dict(self):
        attributes = super(LTECCMUplinkNPrach, self).as_dict()
        self.n_prach_params = self.filter_empty_parameters(self.n_prach_params)
        attributes['params']['nPrachParams'] = self.n_prach_params

        return attributes
